const WORDS: WordEntry[] = [
  ...wordsA1A2,
  ...wordsB1B2,
  ...wordsC1C2,
];

function seedVocabulary(): void {
  runMigrations();
  const db = getDb();

  const insertStmt = db.prepare(`
    INSERT INTO vocabulary_words
      (english_word, russian_translation, accepted_translations, example_en, example_ru, difficulty)
    VALUES (?, ?, ?, ?, ?, ?)
    ON CONFLICT(english_word) DO UPDATE SET
      russian_translation = excluded.russian_translation,
      accepted_translations = excluded.accepted_translations,
      example_en = excluded.example_en,
      example_ru = excluded.example_ru,
      difficulty = excluded.difficulty,
      updated_at = datetime('now')
  `);

  const insertMany = db.transaction((words: WordEntry[]) => {
    let processed = 0;
    for (const w of words) {
      const result = insertStmt.run(
        w.english_word,
        w.russian_translation,
        JSON.stringify(w.accepted_translations ?? []),
        w.example_en ?? null,
        w.example_ru ?? null,
        w.difficulty,
      );
      if (result.changes > 0) processed++;
    }
    return processed;
  });

  const processed = insertMany(WORDS);
  logger.info({ total: WORDS.length, processed }, 'Словарь наполнен');
  console.log(`✅ Обработано слов: ${processed} (всего в сиде: ${WORDS.length})`);
}

seedVocabulary();
closeDb();
